-- Additive only. Preserve all seven original tables and records. Apply ONCE via setup.py.
CREATE TABLE schema_versions (version VARCHAR(50) PRIMARY KEY, installed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
ALTER TABLE users ADD university_id VARCHAR(100) NULL UNIQUE, ADD department_id INT NULL, ADD password_changed_at DATETIME NULL;
ALTER TABLE laboratories ADD department_id INT NULL, ADD administrator_id INT NULL, ADD is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE categories ADD is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE assets ADD property_number VARCHAR(150) NULL UNIQUE, ADD public_token CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL UNIQUE, ADD specifications TEXT NULL, ADD purchase_order_number VARCHAR(150) NULL, ADD fund_source VARCHAR(150) NULL, ADD sticker_location VARCHAR(255) NULL, ADD sticker_end_user VARCHAR(255) NULL, ADD custodian_id INT NULL, ADD department_id INT NULL, ADD acquisition_amount DECIMAL(15,2) NULL, ADD is_borrowable BOOLEAN NOT NULL DEFAULT FALSE, ADD archived_at DATETIME NULL;
ALTER TABLE activity_logs ADD previous_values JSON NULL, ADD updated_values JSON NULL, ADD ip_address VARCHAR(45) NULL;
CREATE TABLE roles (code VARCHAR(20) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE role_aliases (legacy_code VARCHAR(20) PRIMARY KEY, role_code VARCHAR(20) NOT NULL, FOREIGN KEY(role_code) REFERENCES roles(code)) ENGINE=InnoDB;
CREATE TABLE permissions (code VARCHAR(100) PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_code VARCHAR(20) NOT NULL, permission_code VARCHAR(100) NOT NULL, PRIMARY KEY(role_code,permission_code), FOREIGN KEY(role_code) REFERENCES roles(code), FOREIGN KEY(permission_code) REFERENCES permissions(code)) ENGINE=InnoDB;
CREATE TABLE departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
ALTER TABLE users ADD FOREIGN KEY (department_id) REFERENCES departments(id);
ALTER TABLE laboratories ADD FOREIGN KEY (department_id) REFERENCES departments(id), ADD FOREIGN KEY (administrator_id) REFERENCES users(id);
ALTER TABLE assets ADD FOREIGN KEY (department_id) REFERENCES departments(id), ADD FOREIGN KEY (custodian_id) REFERENCES users(id), ADD CHECK (acquisition_amount IS NULL OR acquisition_amount>=0);
CREATE TABLE user_laboratories (user_id INT NOT NULL, laboratory_id INT NOT NULL, PRIMARY KEY(user_id,laboratory_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(laboratory_id) REFERENCES laboratories(id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY, identifier_hash CHAR(64) NOT NULL, ip_address VARCHAR(45) NOT NULL, succeeded BOOLEAN NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(identifier_hash,created_at), INDEX(ip_address,created_at)) ENGINE=InnoDB;
CREATE TABLE password_reset_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE workstations (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, laboratory_id INT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(laboratory_id) REFERENCES laboratories(id)) ENGINE=InnoDB;
CREATE TABLE workstation_assets (workstation_id INT NOT NULL, asset_id INT NOT NULL UNIQUE, PRIMARY KEY(workstation_id,asset_id), FOREIGN KEY(workstation_id) REFERENCES workstations(id), FOREIGN KEY(asset_id) REFERENCES assets(id)) ENGINE=InnoDB;
CREATE TABLE borrow_requests (id INT AUTO_INCREMENT PRIMARY KEY, borrower_id INT NOT NULL, purpose TEXT NOT NULL, requested_at DATETIME NOT NULL, expected_return_at DATETIME NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pending', reviewed_by INT NULL, released_by INT NULL, released_at DATETIME NULL, decision_remarks TEXT NULL, FOREIGN KEY(borrower_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id), FOREIGN KEY(released_by) REFERENCES users(id), CHECK(expected_return_at>requested_at)) ENGINE=InnoDB;
CREATE TABLE borrow_items (id INT AUTO_INCREMENT PRIMARY KEY, borrow_request_id INT NOT NULL, asset_id INT NOT NULL, assignment_id INT NULL UNIQUE, returned_at DATETIME NULL, returned_condition VARCHAR(20) NULL, received_by INT NULL, remarks TEXT NULL, UNIQUE(borrow_request_id,asset_id), FOREIGN KEY(borrow_request_id) REFERENCES borrow_requests(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(assignment_id) REFERENCES assignments(id), FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE asset_transaction_locks (asset_id INT PRIMARY KEY, operation VARCHAR(30) NOT NULL, operation_id INT NOT NULL, resolved_at DATETIME NULL, FOREIGN KEY(asset_id) REFERENCES assets(id)) ENGINE=InnoDB;
CREATE TABLE maintenance_requests (id INT AUTO_INCREMENT PRIMARY KEY, asset_id INT NOT NULL, reported_by INT NOT NULL, technician_id INT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'Normal', problem_description TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Reported', closed_at DATETIME NULL, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(reported_by) REFERENCES users(id), FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
ALTER TABLE maintenance_records ADD request_id INT NULL, ADD technician_id INT NULL, ADD exact_cost DECIMAL(15,2) NULL, ADD FOREIGN KEY(request_id) REFERENCES maintenance_requests(id), ADD FOREIGN KEY(technician_id) REFERENCES users(id);
CREATE TABLE asset_transfers (id INT AUTO_INCREMENT PRIMARY KEY, asset_id INT NOT NULL, source_laboratory_id INT NULL, destination_laboratory_id INT NOT NULL, requested_by INT NOT NULL, reviewed_by INT NULL, confirmed_by INT NULL, reason TEXT NOT NULL, transfer_date DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pending', confirmed_at DATETIME NULL, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(source_laboratory_id) REFERENCES laboratories(id), FOREIGN KEY(destination_laboratory_id) REFERENCES laboratories(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id), FOREIGN KEY(confirmed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE inventory_audits (id INT AUTO_INCREMENT PRIMARY KEY, laboratory_id INT NOT NULL, created_by INT NOT NULL, reviewed_by INT NULL, name VARCHAR(200) NOT NULL, scheduled_date DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', completed_at DATETIME NULL, FOREIGN KEY(laboratory_id) REFERENCES laboratories(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE inventory_audit_items (id INT AUTO_INCREMENT PRIMARY KEY, audit_id INT NOT NULL, asset_id INT NOT NULL, property_number_snapshot VARCHAR(150) NULL, expected_laboratory_id INT NULL, observed_laboratory_id INT NULL, inspector_id INT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Not Yet Inspected', inspected_at DATETIME NULL, remarks TEXT NULL, UNIQUE(audit_id,asset_id), FOREIGN KEY(audit_id) REFERENCES inventory_audits(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(expected_laboratory_id) REFERENCES laboratories(id), FOREIGN KEY(observed_laboratory_id) REFERENCES laboratories(id), FOREIGN KEY(inspector_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE asset_disposals (id INT AUTO_INCREMENT PRIMARY KEY, asset_id INT NOT NULL, requested_by INT NOT NULL, approved_by INT NULL, reason TEXT NOT NULL, asset_condition VARCHAR(20) NOT NULL, disposal_date DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pending', FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE attachments (id INT AUTO_INCREMENT PRIMARY KEY, asset_id INT NOT NULL, uploaded_by INT NOT NULL, maintenance_request_id INT NULL, borrow_item_id INT NULL, disposal_id INT NULL, kind VARCHAR(30) NOT NULL, storage_key VARCHAR(255) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(uploaded_by) REFERENCES users(id), FOREIGN KEY(maintenance_request_id) REFERENCES maintenance_requests(id), FOREIGN KEY(borrow_item_id) REFERENCES borrow_items(id), FOREIGN KEY(disposal_id) REFERENCES asset_disposals(id)) ENGINE=InnoDB;
CREATE TABLE asset_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, asset_id INT NOT NULL, actor_id INT NOT NULL, event VARCHAR(100) NOT NULL, previous_values JSON NULL, updated_values JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, type VARCHAR(100) NOT NULL, message VARCHAR(500) NOT NULL, related_module VARCHAR(50) NOT NULL, related_record_id INT NULL, deduplication_key VARCHAR(191) NULL UNIQUE, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE system_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value JSON NOT NULL, updated_by INT NULL, FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB;
